import type { EdgeChange, NodeChange, SelectionChange } from "@xyflow/system";
import type { FlowEdge, FlowNode } from "#/lib/xyflow/types";

type ElementChange<T> = { id?: string; type: string; index?: number; item?: T | Partial<T> };

function applyChanges<T extends { id: string }>(changes: ElementChange<T>[], elements: T[]): T[] {
  const updated: T[] = [];
  const changesMap = new Map<string, ElementChange<T>[]>();
  const additions: ElementChange<T>[] = [];

  for (const change of changes) {
    if (change.type === "add") {
      additions.push(change);
      continue;
    }
    if (change.type === "remove" || change.type === "replace") {
      if (change.id) changesMap.set(change.id, [change]);
      continue;
    }
    if (!change.id) continue;
    const queued = changesMap.get(change.id);
    if (queued) queued.push(change);
    else changesMap.set(change.id, [change]);
  }

  for (const element of elements) {
    const elementChanges = changesMap.get(element.id);
    if (!elementChanges) {
      updated.push(element);
      continue;
    }
    if (elementChanges[0]?.type === "remove") continue;
    if (elementChanges[0]?.type === "replace" && elementChanges[0].item) {
      updated.push(elementChanges[0].item as T);
      continue;
    }
    const next = { ...element };
    for (const change of elementChanges) applyChange(change, next);
    updated.push(next);
  }

  for (const change of additions) {
    if (!change.item) continue;
    const item = change.item as T;
    if (change.index !== undefined) updated.splice(change.index, 0, item);
    else updated.push(item);
  }

  return updated;
}

function applyChange(
  change: { type: string; [key: string]: unknown },
  element: Record<string, unknown>,
) {
  switch (change.type) {
    case "select":
      element.selected = change.selected;
      break;
    case "position":
      if (change.position !== undefined) element.position = change.position;
      if (change.dragging !== undefined) element.dragging = change.dragging;
      break;
    case "dimensions":
      if (change.dimensions !== undefined) {
        element.measured = { ...(change.dimensions as object) };
        if (change.setAttributes === true || change.setAttributes === "width") {
          element.width = (change.dimensions as { width?: number }).width;
        }
        if (change.setAttributes === true || change.setAttributes === "height") {
          element.height = (change.dimensions as { height?: number }).height;
        }
      }
      break;
    case "update":
      // Shallow-merges a partial element (@xyflow/system 1.0 `UpdateChange`).
      if (change.item && typeof change.item === "object") Object.assign(element, change.item);
      break;
    case "data":
      // Merges into `data`, or replaces it when `replace` is set (`DataChange`).
      element.data = change.replace
        ? change.data
        : { ...(element.data as object | undefined), ...(change.data as object) };
      break;
    default:
      break;
  }
}

export function applyNodeChanges(changes: NodeChange<FlowNode>[], nodes: FlowNode[]): FlowNode[] {
  return applyChanges(changes, nodes);
}

export function applyEdgeChanges(changes: EdgeChange<FlowEdge>[], edges: FlowEdge[]): FlowEdge[] {
  return applyChanges(changes, edges);
}

export function createSelectionChange(id: string, selected: boolean): SelectionChange {
  return { id, type: "select", selected };
}

export function getSelectionChanges(
  items: Map<string, { id: string; selected?: boolean }>,
  selectedIds: Set<string> = new Set(),
): Array<SelectionChange> {
  const changes: Array<SelectionChange> = [];
  for (const [id, item] of items) {
    const willBeSelected = selectedIds.has(id);
    if (!(item.selected === undefined && !willBeSelected) && item.selected !== willBeSelected) {
      changes.push(createSelectionChange(item.id, willBeSelected));
    }
  }
  return changes;
}

export function cx(
  ...parts: Array<string | false | null | undefined | Record<string, boolean | undefined>>
): string {
  const out: string[] = [];
  for (const part of parts) {
    if (!part) continue;
    if (typeof part === "string") {
      out.push(part);
      continue;
    }
    for (const key in part) {
      if (part[key]) out.push(key);
    }
  }
  return out.join(" ");
}

